from pathlib import Path
import base64,io,zipfile,subprocess,sys,os
A=Path('/kaggle/working/rascar_v25')
zipfile.ZipFile(io.BytesIO(base64.b64decode(''))).extractall(A)
subprocess.run([sys.executable,'-m','pip','uninstall','-y','onnxruntime'],check=True)
subprocess.run([sys.executable,'-m','pip','install','--force-reinstall','--no-deps','-q','onnxruntime-gpu'],check=True)
pose_jobs={}
for gpu,kind in enumerate(['rtmw','wilor_detector']):
 pose_jobs[kind]=subprocess.Popen([sys.executable,'-u',str(A/'benchmark.py'),kind],stdout=open(A/(kind+'.log'),'w'),stderr=subprocess.STDOUT,env=dict(os.environ,CUDA_VISIBLE_DEVICES=str(gpu)))
print('POSE_JOBS_STARTED',{k:v.pid for k,v in pose_jobs.items()})
